'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let config={url:sessionStorage.getItem('engineUrl')||'',key:sessionStorage.getItem('engineKey')||''},connected=false,mode='url',file=null,currentJob=null,activeClip=null,pollTimer=null,sourceObject=null,exportBusy=false,exportsList=[];
let projects=JSON.parse(localStorage.getItem('chinduProjects')||'[]');
const demo={id:'demo',demo:true,title:'Créer un message qui reste',duration:30,status:'done',clips:[{id:'1',start:0,end:10,title:'Pourquoi certains messages restent en mémoire',score:89,reason:'Une question directe et une idée facile à retenir.',cues:[{start:0,end:4,text:'Pourquoi certains messages restent en mémoire ?'},{start:4,end:7,text:'Tout commence par une idée claire.'},{start:7,end:10,text:'Et une phrase qui donne envie d’écouter.'}]},{id:'2',start:10,end:20,title:'L’erreur qui affaiblit votre prise de parole',score:85,reason:'Une erreur concrète introduit un conseil immédiatement utile.',cues:[{start:10,end:14,text:'L’erreur, c’est de vouloir tout dire.'},{start:14,end:17,text:'Choisissez une seule idée.'},{start:17,end:20,text:'Puis donnez-lui un exemple concret.'}]},{id:'3',start:20,end:30,title:'Une histoire vaut mieux qu’une liste',score:80,reason:'Un contraste simple et une conclusion autonome.',cues:[{start:20,end:24,text:'Une histoire nous aide à comprendre.'},{start:24,end:27,text:'Montrez le problème, puis la solution.'},{start:27,end:30,text:'Laissez une idée à emporter.'}]}]};
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function time(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
async function api(path,options={}){if(!connected&&!options.testing)throw Error('Connectez votre moteur vidéo dans les paramètres.');const {testing,...fetchOptions}=options;const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),path.startsWith('/api/export')?1800000:120000);try{const r=await fetch(config.url+path,{...fetchOptions,signal:controller.signal,headers:{Authorization:'Bearer '+config.key,...fetchOptions.headers}});if(!r.ok){let message;try{message=(await r.json()).error;}catch{}throw Error(message||`Le moteur a répondu avec une erreur (${r.status}).`);}return r;}catch(e){if(e.name==='AbortError')throw Error('Le moteur met trop de temps à répondre. Vérifiez son état.');if(e instanceof TypeError)throw Error('Moteur inaccessible. Vérifiez son adresse HTTPS, sa disponibilité et les origines autorisées.');throw e;}finally{clearTimeout(timer);}}
function setConnected(value){connected=value;$('#engineStatus').classList.toggle('connected',value);$('#engineStatus').innerHTML=`<span class="status-dot"></span> ${value?'Moteur connecté':'Moteur non connecté'} <span>↗</span>`;$('#notice').hidden=value;}
function showSettings(){$('#engineUrl').value=config.url;$('#engineKey').value=config.key;$('#connectionResult').textContent='';$('#settingsDialog').showModal();}
$$('.settings-trigger').forEach(b=>b.onclick=showSettings);$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
$('#settingsForm').onsubmit=async e=>{e.preventDefault();const raw=$('#engineUrl').value.trim().replace(/\/+$/,'');let u;try{u=new URL(raw);if(u.username||u.password||u.search||u.hash||u.pathname!=='/'||!(u.protocol==='https:'||(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname))))throw Error();}catch{$('#connectionResult').textContent='Utilisez une origine HTTPS (sans chemin) ou http://localhost:8080.';return;}const previous={...config};config={url:raw,key:$('#engineKey').value};$('#connectBtn').disabled=true;$('#connectionResult').textContent='Connexion au moteur…';try{const r=await api('/api/health',{testing:true});const h=await r.json();if(!h.ok)throw Error('Réponse moteur invalide.');sessionStorage.setItem('engineUrl',config.url);sessionStorage.setItem('engineKey',config.key);setConnected(true);$('#settingsDialog').close();toast('Moteur connecté. Votre studio est prêt.');loadProjects();}catch(e){config=previous;$('#connectionResult').textContent=e.message;}finally{$('#connectBtn').disabled=false;}};
$('#disconnectBtn').onclick=()=>{sessionStorage.removeItem('engineUrl');sessionStorage.removeItem('engineKey');config={url:'',key:''};setConnected(false);$('#engineKey').value='';$('#engineUrl').value='';$('#connectionResult').textContent='Moteur déconnecté de cet onglet.';clearTimeout(pollTimer);};
function setMode(m){mode=m;$('#urlTab').classList.toggle('selected',m==='url');$('#fileTab').classList.toggle('selected',m==='file');$('#urlInputWrap').hidden=m!=='url';$('#fileInputWrap').hidden=m!=='file';$('#videoUrl').required=m==='url';}$('#urlTab').onclick=()=>setMode('url');$('#fileTab').onclick=()=>setMode('file');
function chooseFile(f){if(!f)return;if(!f.type.startsWith('video/'))return toast('Choisissez un fichier vidéo.');if(f.size>400*1024*1024)return toast('La taille maximale est de 400 Mo.');file=f;$('#fileName').textContent=f.name;}
$('#videoFile').onchange=e=>chooseFile(e.target.files[0]);$('#dropzone').ondragover=e=>e.preventDefault();$('#dropzone').ondrop=e=>{e.preventDefault();chooseFile(e.dataTransfer.files[0]);};
function youtubeId(s){try{const u=new URL(s);if(u.protocol!=='https:'||!['youtube.com','www.youtube.com','m.youtube.com','youtu.be'].includes(u.hostname))return null;const id=u.hostname==='youtu.be'?u.pathname.slice(1).split('/')[0]:u.pathname==='/watch'?u.searchParams.get('v'):u.pathname.match(/^\/(?:shorts|live)\/([^/]+)/)?.[1];return /^[\w-]{11}$/.test(id||'')?id:null;}catch{return null;}}
$('#importForm').onsubmit=async e=>{e.preventDefault();if(mode==='url'&&!youtubeId($('#videoUrl').value.trim()))return toast('Collez le lien HTTPS d’une vidéo YouTube valide.');if(mode==='file'&&!file)return toast('Choisissez d’abord une vidéo.');if(!connected){showSettings();return;}const [min,max]=$('#duration').value.split(',').map(Number),o={language:$('#language').value,min_duration:min,max_duration:max,count:Number($('#clipCount').value)};$('#analyzeBtn').disabled=true;$('.file-submit').disabled=true;try{let r;if(mode==='url')r=await api('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...o,url:$('#videoUrl').value.trim()})});else r=await api('/api/upload?'+new URLSearchParams({...o,name:file.name}),{method:'POST',headers:{'Content-Type':file.type},body:file});currentJob=await r.json();remember(currentJob);$('#resultsSection').hidden=true;$('#emptyState').hidden=true;pollJob(currentJob.id);}catch(e){toast(e.message);}finally{$('#analyzeBtn').disabled=false;$('.file-submit').disabled=false;}};
function remember(j){if(j.demo)return;projects=[{...j,engine:config.url},...projects.filter(p=>p.id!==j.id)].slice(0,30);localStorage.setItem('chinduProjects',JSON.stringify(projects));$('#projectCount').textContent=projects.length;}
async function pollJob(id){clearTimeout(pollTimer);$('#progressSection').hidden=false;try{const j=await(await api('/api/jobs/'+id)).json();currentJob=j;remember(j);$('#progressLabel').textContent=j.stage;$('#progressNumber').textContent=(j.progress||0)+' %';$('#progress').value=j.progress||0;if(j.status==='done'){$('#progressSection').hidden=true;renderClips();return;}if(j.status==='error'){$('#progressSection').hidden=true;$('#emptyState').hidden=false;toast(j.error);return;}pollTimer=setTimeout(()=>pollJob(id),3000);}catch(e){$('#progressSection').hidden=true;toast(e.message+' Retrouvez le projet dans « Mes projets » pour reprendre.');}}
$('#demoBtn').onclick=()=>{clearTimeout(pollTimer);currentJob=structuredClone(demo);$('#progressSection').hidden=true;renderClips();$('#resultsSection').scrollIntoView({behavior:'smooth',block:'start'});};
function renderClips(){$('#emptyState').hidden=true;$('#resultsSection').hidden=false;$('#resultBadge').textContent=currentJob.demo?'DÉMONSTRATION · EXEMPLES PRÉPARÉS':'VOTRE SÉLECTION';$('#resultTitle').textContent='Les moments à retenir';$('#resultDescription').textContent=currentJob.demo?'3 exemples pour explorer l’éditeur. Ils ne proviennent pas de votre lien.':`${currentJob.clips.length} extraits proposés · ${currentJob.title}`;const clips=[...currentJob.clips].sort($('#sortClips').value==='time'?(a,b)=>a.start-b.start:(a,b)=>b.score-a.score);$('#clipsGrid').innerHTML=clips.map((c,i)=>`<article class="clip-card"><div class="clip-art color-${i%3}"><input class="clip-check" type="checkbox" data-id="${esc(c.id)}" ${c.selected===false?'':'checked'} aria-label="Sélectionner cet extrait"><span class="clip-tag">${currentJob.demo?'EXEMPLE':'EXTRAIT '+(i+1)}</span><span class="art-title">${esc(c.title)}</span><button class="clip-play" data-edit="${esc(c.id)}" aria-label="Lire l’extrait">▶</button><span class="clip-length">${Math.round(c.end-c.start)} s</span></div><div class="clip-body"><div class="clip-meta"><span>${time(c.start)} — ${time(c.end)}</span><span class="score">✦ ${c.score}/100</span></div><h3>${esc(c.title)}</h3><p>${esc(c.reason)}</p><button class="secondary" data-edit="${esc(c.id)}">Aperçu & ajustements ↗</button></div></article>`).join('');$$('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.edit));$$('.clip-check').forEach(b=>b.onchange=()=>{currentJob.clips.find(c=>c.id===b.dataset.id).selected=b.checked;if(!currentJob.demo)remember(currentJob);});}
$('#sortClips').onchange=()=>currentJob&&renderClips();
function srt(cues,start,end){const fmt=v=>{let n=Math.max(0,Math.round(v*1000));const h=Math.floor(n/3600000);n%=3600000;const m=Math.floor(n/60000);n%=60000;const s=Math.floor(n/1000);return [h,m,s].map(x=>String(x).padStart(2,'0')).join(':')+','+String(n%1000).padStart(3,'0');};let idx=0;return cues.filter(c=>c.end>start&&c.start<end).map(c=>`${++idx}\n${fmt(Math.max(c.start,start)-start)} --> ${fmt(Math.min(c.end,end)-start)}\n${c.text.replace(/[\r\n]/g,' ')}\n`).join('\n');}
function saveBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);}
async function openEditor(id){activeClip=currentJob.clips.find(c=>c.id===id);$('#editorTitle').textContent=activeClip.title;$('#editorBadge').textContent=currentJob.demo?'DÉMONSTRATION · EXEMPLE':'ÉDITEUR';$('#clipStart').value=activeClip.start;$('#clipEnd').value=activeClip.end;$('#exportStatus').textContent='';$('#aspect').value=activeClip.aspect||'9:16';$('#captionStyle').value=activeClip.style||'bold';$('#includeCaptions').checked=activeClip.subtitles!==false;$('#cueEditor').innerHTML=activeClip.cues.map((c,i)=>`<label class="cue-row"><span>${time(c.start)}</span><textarea data-cue="${i}" aria-label="Sous-titre à ${time(c.start)}">${esc(c.text)}</textarea></label>`).join('');$$('[data-cue]').forEach(t=>t.oninput=()=>{activeClip.cues[Number(t.dataset.cue)].text=t.value;});const video=$('#editorVideo');video.pause();video.removeAttribute('src');video.load();$('#captionOverlay').textContent='';$('#editorDialog').showModal();updateCut();if(currentJob.demo){video.src='/demo.mp4';$('#previewNote').textContent='Vidéo graphique de démonstration. Les textes ci-contre sont des exemples modifiables.';}else{$('#previewNote').textContent='Chargement de la source pour l’aperçu…';try{if(sourceObject)URL.revokeObjectURL(sourceObject);sourceObject=URL.createObjectURL(await(await api('/api/files/'+currentJob.id+'/source.mp4')).blob());if(!$('#editorDialog').open)return;video.src=sourceObject;$('#previewNote').textContent='Aperçu de la source. Le format et les sous-titres sont appliqués à l’export.';}catch(e){$('#previewNote').textContent=e.message;}}video.onloadedmetadata=()=>{video.currentTime=activeClip.start;};}
function updateCut(){if(!activeClip)return;const a=Number($('#clipStart').value),b=Number($('#clipEnd').value);$('#cutDuration').textContent=`Durée : ${Math.max(0,b-a).toFixed(1)} secondes`;}
function refreshCues(){if(!activeClip||!currentJob?.transcript)return;const a=Number($('#clipStart').value),b=Number($('#clipEnd').value),existing=new Set(activeClip.cues.map(c=>c.start));for(const c of currentJob.transcript){if(c.end>a&&c.start<b&&!existing.has(c.start))activeClip.cues.push({...c});}activeClip.cues.sort((x,y)=>x.start-y.start);$('#cueEditor').innerHTML=activeClip.cues.map((c,i)=>c.end>a&&c.start<b?`<label class="cue-row"><span>${time(c.start)}</span><textarea data-cue="${i}" aria-label="Sous-titre à ${time(c.start)}">${esc(c.text)}</textarea></label>`:'').join('');$$('[data-cue]').forEach(t=>t.oninput=()=>{activeClip.cues[Number(t.dataset.cue)].text=t.value;});}
function commitCut(){if(!activeClip)return false;const a=Number($('#clipStart').value),b=Number($('#clipEnd').value);if(!(a>=0&&b>a&&b<=currentJob.duration+.1&&b-a<=180)){toast('Vérifiez les bornes : début < fin, dans la vidéo, maximum 180 secondes.');return false;}activeClip.start=a;activeClip.end=b;activeClip.aspect=$('#aspect').value;activeClip.style=$('#captionStyle').value;activeClip.subtitles=$('#includeCaptions').checked;return true;}
$('#clipStart').oninput=updateCut;$('#clipEnd').oninput=updateCut;$('#clipStart').onchange=refreshCues;$('#clipEnd').onchange=refreshCues;
$('#playClip').onclick=()=>{if(!commitCut())return;const v=$('#editorVideo');v.currentTime=activeClip.start;v.play().catch(()=>toast('L’aperçu vidéo est indisponible.'));};
$('#editorVideo').ontimeupdate=()=>{if(!activeClip)return;const v=$('#editorVideo'),cue=activeClip.cues.find(c=>c.start<=v.currentTime&&c.end>v.currentTime);$('#captionOverlay').textContent=$('#includeCaptions').checked&&cue?cue.text:'';$('#captionOverlay').style.color=$('#captionStyle').value==='yellow'?'#fff000':'white';$('#captionOverlay').style.fontWeight=$('#captionStyle').value==='clean'?'400':'700';if(v.currentTime>=Number($('#clipEnd').value)&&!v.paused)v.pause();};
$('#editorDialog').addEventListener('close',()=>{$('#editorVideo').pause();commitCut();if(currentJob&&!currentJob.demo)remember(currentJob);if(currentJob)renderClips();});
$('#downloadSrt').onclick=()=>{if(commitCut())saveBlob(new Blob([srt(activeClip.cues,activeClip.start,activeClip.end)],{type:'application/x-subrip;charset=utf-8'}),'chindu-'+(currentJob.demo?'exemple-':'')+activeClip.id+'.srt');};
async function exportOne(c){if(currentJob.demo){saveBlob(await(await fetch('/demo.mp4')).blob(),'chindu-demonstration-30s.mp4');exportsList.push({name:'Vidéo de démonstration (30 s)',date:new Date().toLocaleString('fr-FR'),demo:true});return;}const options={start:c.start,end:c.end,cues:c.cues,aspect:c.aspect||'9:16',style:c.style||'bold',subtitles:c.subtitles!==false};const result=await(await api('/api/export/'+currentJob.id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(options)})).json();const blob=await(await api('/api/files/'+currentJob.id+'/'+result.file)).blob();saveBlob(blob,'chindu-'+c.id+'.mp4');exportsList.push({name:c.title,date:new Date().toLocaleString('fr-FR'),jobId:currentJob.id,file:result.file});}
$('#exportClip').onclick=async()=>{if(exportBusy||!commitCut())return;exportBusy=true;$('#exportClip').disabled=true;$('#exportStatus').textContent=currentJob.demo?'Téléchargement de la vidéo de démonstration complète…':'Rendu MP4 en cours. Cela peut prendre quelques minutes…';try{await exportOne(activeClip);$('#exportStatus').textContent=currentJob.demo?'Vidéo exemple complète téléchargée (30 s). Le découpage nécessite le moteur.':'MP4 téléchargé avec vos réglages.';}catch(e){$('#exportStatus').textContent=e.message;}finally{exportBusy=false;$('#exportClip').disabled=false;}};
$('#exportSelected').onclick=async()=>{if(exportBusy)return;const selected=currentJob.clips.filter(c=>c.selected!==false);if(!selected.length)return toast('Sélectionnez au moins un extrait.');if(currentJob.demo){openEditor(selected[0].id);toast('Exemple : explorez l’éditeur. Les exports découpés nécessitent le moteur.');return;}exportBusy=true;$('#exportSelected').disabled=true;try{for(let i=0;i<selected.length;i++){toast(`Export ${i+1}/${selected.length} en cours…`);await exportOne(selected[i]);}toast('Votre sélection a été téléchargée.');}catch(e){toast(e.message);}finally{exportBusy=false;$('#exportSelected').disabled=false;}};
function page(name){['studio','projects','exports'].forEach(p=>$('#'+p+'Page').hidden=p!==name);$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('#pageCrumb').textContent={studio:'Studio de clips',projects:'Mes projets',exports:'Mes exports'}[name];if(name==='projects')renderProjects();if(name==='exports')renderExports();}
$$('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();page('studio');};
async function loadProjects(){try{const jobs=await(await api('/api/jobs')).json();for(const j of jobs)remember(j);renderProjects();}catch(e){toast(e.message);}}
function renderProjects(){$('#projectCount').textContent=projects.length;if(!projects.length){$('#projectsList').innerHTML='<div class="empty-panel"><h3>Votre prochain projet commence ici.</h3><p>Importez une vidéo dans le studio.<br>Les projets analysés apparaîtront dans cet espace.</p><button class="primary" id="backToStudio">Créer un projet ↗</button></div>';$('#backToStudio').onclick=()=>page('studio');return;}$('#projectsList').innerHTML=projects.map(j=>`<div class="project-row"><div><h3>${esc(j.title)}</h3><p>${new Date(j.created*1000).toLocaleDateString('fr-FR')} · ${esc({done:'Extraits prêts',queued:'En attente',processing:'En cours',error:'Traitement interrompu'}[j.status]||j.status)} · ${j.clips?.length||0} extrait(s)</p></div><button class="secondary" data-open="${esc(j.id)}">Ouvrir ↗</button><button class="text-btn" data-delete="${esc(j.id)}">Supprimer</button></div>`).join('');$$('[data-open]').forEach(b=>b.onclick=()=>{const j=projects.find(x=>x.id===b.dataset.open);if(j.status==='done'){currentJob=structuredClone(j);page('studio');renderClips();}else if(connected&&j.engine===config.url){page('studio');pollJob(j.id);}else showSettings();});$$('[data-delete]').forEach(b=>b.onclick=async()=>{const j=projects.find(x=>x.id===b.dataset.delete);if(!confirm('Supprimer ce projet et ses fichiers du moteur ?'))return;if(!connected||j.engine!==config.url){toast('Connectez le moteur de ce projet pour supprimer ses fichiers.');return;}try{await api('/api/jobs/'+j.id,{method:'DELETE'});projects=projects.filter(x=>x.id!==j.id);localStorage.setItem('chinduProjects',JSON.stringify(projects));renderProjects();toast('Projet et fichiers supprimés.');}catch(e){toast(e.message);}});}
function renderExports(){$('#exportsList').innerHTML=exportsList.length?exportsList.map((x,i)=>`<div class="export-row"><div><h3>${esc(x.name)}</h3><p>${esc(x.date)} · ${x.demo?'Démonstration':'MP4'}</p></div><button class="secondary" data-download="${i}">Télécharger ↓</button></div>`).join(''):'<div class="empty-panel"><h3>Votre prochaine publication se prépare.</h3><p>Les MP4 exportés pendant cette session apparaîtront ici.<br>Vos fichiers restent disponibles dans le dossier de téléchargement de votre appareil.</p></div>';$$('[data-download]').forEach(b=>b.onclick=async()=>{const x=exportsList[Number(b.dataset.download)];try{const blob=x.demo?await(await fetch('/demo.mp4')).blob():await(await api('/api/files/'+x.jobId+'/'+x.file)).blob();saveBlob(blob,'chindu-'+(x.demo?'demonstration':x.file)+'.mp4');}catch(e){toast(e.message);}});}
$('#projectCount').textContent=projects.length;setMode('url');if(config.url&&config.key)api('/api/health',{testing:true}).then(r=>r.json()).then(h=>{setConnected(Boolean(h.ok));if(h.ok)loadProjects();}).catch(()=>setConnected(false));
